<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { UiAlert } from '@go-tangra/ui'
import { get, explain } from '@/api/client'
import { useLatest } from '@/components/latest'
import { dayBars, formatDuration, type DayBar, type DayPiece } from '@/components/day-bars'
import { pbxTimezone } from '@/components/timezone'
import type { RegistrationTimeline } from '@/api/types'
// The API serves at most 31 days; a longer period shows its last 31 days.
const MAX_DAYS=31
const props=defineProps<{extension:string;from:string;to:string}>();const emit=defineEmits<{loaded:[RegistrationTimeline|undefined]}>();const timeline=ref<RegistrationTimeline>(),error=ref(''),loading=ref(false),picked=ref<DayPiece>()
const request=useLatest()
const range=computed(()=>{const to=Date.parse(props.to),from=Math.max(Date.parse(props.from),to-MAX_DAYS*86_400_000);return {from:new Date(from).toISOString(),to:new Date(to).toISOString(),clipped:from>Date.parse(props.from)}})
async function load(){const signal=request.start();error.value='';picked.value=undefined;loading.value=true;try{const v=await get<RegistrationTimeline>('/api/asterisk/registration/timeline/{extension}',{from:range.value.from,to:range.value.to},{extension:props.extension},signal);if(!signal.aborted){timeline.value=v;emit('loaded',v)}}catch(e){if(!signal.aborted){timeline.value=undefined;emit('loaded',undefined);error.value=explain(e)}}finally{if(!signal.aborted)loading.value=false}}
onMounted(load);watch(()=>[props.extension,props.from,props.to],load)
const days=computed(()=>timeline.value?dayBars(timeline.value,pbxTimezone.value).reverse():[])
const STATE={online:{label:'Online',fill:'fill-success'},offline:{label:'Offline',fill:'fill-error'},unknown:{label:'No data',fill:'fill-base-content/25'}} as const
const clock=(iso:string)=>new Intl.DateTimeFormat('en-GB',{timeZone:pbxTimezone.value,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(iso))
const dayLabel=(b:DayBar)=>new Intl.DateTimeFormat('en-GB',{timeZone:pbxTimezone.value,weekday:'short',day:'2-digit',month:'2-digit'}).format(new Date(b.start))
const span=(p:DayPiece)=>`${clock(p.start)}–${clock(p.end)} ${STATE[p.state].label.toLowerCase()} (${formatDuration((Date.parse(p.end)-Date.parse(p.start))/1000)})`
const describe=(b:DayBar)=>`${dayLabel(b)}: `+(['online','offline','unknown'] as const).filter(s=>b.totals[s]>0).map(s=>`${STATE[s].label.toLowerCase()} ${formatDuration(b.totals[s])}`).join(', ')
</script>
<template><div class="space-y-2"><UiAlert v-if="error" kind="warning">{{error}}</UiAlert><UiAlert v-if="range.clipped" kind="info">The timeline shows the last {{MAX_DAYS}} days of this period.</UiAlert><p v-if="loading&&!timeline">Loading the registration timeline…</p><template v-if="timeline"><p data-test="timeline-summary"><span class="font-semibold">Online {{formatDuration(timeline.summary.onlineSeconds)}}</span> · Offline {{formatDuration(timeline.summary.offlineSeconds)}} · No data {{formatDuration(timeline.summary.unknownSeconds)}} · {{timeline.summary.dropouts}} {{timeline.summary.dropouts===1?'dropout':'dropouts'}}<template v-if="timeline.summary.longestOfflineSeconds"> · longest offline {{formatDuration(timeline.summary.longestOfflineSeconds)}}</template></p><ul class="flex flex-wrap gap-3" aria-label="Legend"><li v-for="(s,key) in STATE" :key="key" class="flex items-center gap-1"><svg viewBox="0 0 10 10" class="w-3 h-3" aria-hidden="true"><rect width="10" height="10" rx="2" :class="s.fill"/></svg>{{s.label}}</li></ul><p v-if="!days.length">No registration data in this period.</p><ol class="space-y-1" aria-label="Registration by day"><li v-for="b in days" :key="b.day" class="grid grid-cols-[5.5rem_1fr] items-center gap-2"><span class="font-mono">{{dayLabel(b)}}</span><svg :viewBox="`0 0 ${b.length} 10`" preserveAspectRatio="none" class="w-full h-5" role="group" :aria-label="describe(b)"><rect :width="b.length" height="10" class="fill-base-content/5"/><rect v-for="p in b.pieces" :key="p.start" :x="p.x" :width="p.width" height="10" :class="[STATE[p.state].fill,'cursor-pointer']" tabindex="0" role="button" :aria-label="span(p)" @click="picked=p" @keydown.enter.prevent="picked=p" @keydown.space.prevent="picked=p"><title>{{span(p)}}{{p.contact?' · '+p.contact:''}}</title></rect></svg></li></ol><div v-if="days.length" class="grid grid-cols-[5.5rem_1fr] gap-2" aria-hidden="true"><span/><span class="flex justify-between font-mono"><span v-for="h in ['00','06','12','18','24']" :key="h">{{h}}</span></span></div><p v-if="picked" data-test="timeline-picked">{{span(picked)}}<template v-if="picked.contact"> · {{picked.contact}}</template><template v-if="picked.userAgent"> · {{picked.userAgent}}</template><template v-if="picked.viaAddress"> · via {{picked.viaAddress}}</template></p><p v-else-if="days.length">Times in {{pbxTimezone}}. Select a segment for its contact and device.</p></template></div></template>
